<file path="src/invoices.js">
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate date format and value
  const dateRegex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const dateMatch = dateRegex.exec(issueDate);
  if (!dateMatch) return fail('DATE_INVALID');

  const [, year, month, day] = dateMatch;
  const date = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
  if (date.toISOString().slice(0, 10) !== issueDate) {
    return fail('DATE_INVALID');
  }

  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return fail('UNKNOWN_SKU');

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total amount for a line item (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal and total for an invoice (in cents).
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }}
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
  }
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {{ sku: string, qty: number }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  const newLines = invoice.lines.map((l) => ({ ...l }));

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice by assigning a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}
</file>

<file path="src/money.js">
import { ok, fail } from './result.js';

/**
 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
 * @param {number} x
 * @returns {number}
 */
export function roundCents(x) {
  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
 * @param {string} text
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}
</file>

<file path="src/numbering.js">
/**
 * Calculate the next invoice number for a given issue date.
 * Existing numbers can be in any order or format; invalid ones are ignored.
 * @param {string[]} existingNumbers
 * @param {string} issueDate - YYYY-MM-DD format
 * @returns {string}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.slice(0, 4);
  const prefix = `INV-${year}-`;

  const countersForYear = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => {
      const counter = num.slice(prefix.length);
      return parseInt(counter, 10);
    })
    .filter((n) => !isNaN(n));

  const maxCounter = countersForYear.length > 0 ? Math.max(...countersForYear) : 0;
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}
</file>

<file path="src/render.js">
import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const number = invoice.number ?? 'DRAFT';
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;

  const lines = [number, customerName];

  let total = 0;
  for (const line of invoice.lines) {
    const lineAmount = line.qty * line.unitPrice;
    lines.push(
      `${line.qty} ${line.name} ${formatEuros(line.unitPrice)} ${formatEuros(lineAmount)}`
    );
    total += lineAmount;
  }

  lines.push(`Total: ${formatEuros(total)}`);

  return lines.join('\n');
}
</file>

<file path="src/result.js">
/**
 * A successful result.
 * @template T
 * @param {T} value
 * @returns {{ ok: true, value: T }}
 */
export function ok(value) {
  return { ok: true, value };
}

/**
 * A failed result. `error` is an error code from ERRORS in src/errors.js.
 * @param {string} error
 * @param {unknown} [details]
 * @returns {{ ok: false, error: string, details?: unknown }}
 */
export function fail(error, details) {
  return details === undefined ? { ok: false, error } : { ok: false, error, details };
}
</file>

